import assert from 'node:assert/strict';
import test from 'node:test';
import { readFile } from 'node:fs/promises';

import strings from '../../quick-reply-ext/src/strings.js';
import { ROSTER_HEADER, withRosterHeader } from '../../quick-reply-ext/src/promptModifiers.js';

// The official roster's header was "NEVER describe named characters without [<name> INFO]", which Lucky suspected the
// model reads as "never describe a named character". It is swapped at runtime (strings.js is regenerated by Fox's masters).

test('the official roster keeps every character line and only its header changes', () => {
    const original = String(strings.rsbRT);
    const out = withRosterHeader(original);
    assert.ok(out.startsWith(ROSTER_HEADER + '\n'));
    assert.doesNotMatch(out, /NEVER describe named characters/);
    assert.equal(out.slice(ROSTER_HEADER.length), original.slice(original.indexOf('\n')));
    assert.match(out, /Sam: \(squirrel-girl/);
});

test('the header carries the agreed lines and no year', () => {
    assert.match(ROSTER_HEADER, /^\[CHARACTER ROSTER\]\n- The following is a list of special named NPC's/);
    assert.match(ROSTER_HEADER, /\n- Use these to provide references to characters without making assumptions about other parts of their appearance\.\n/);
    assert.match(ROSTER_HEADER, /\n- NEVER make up fake last names\.$/);
    assert.doesNotMatch(ROSTER_HEADER, /YEAR/i);
});

test('text that is not the official roster, or already converted, passes through unchanged', () => {
    assert.equal(withRosterHeader('something else\nline'), 'something else\nline');
    assert.equal(withRosterHeader(''), '');
    const once = withRosterHeader(String(strings.rsbRT));
    assert.equal(withRosterHeader(once), once, 'running it twice changes nothing');
});

test('XXX applies it where the RT variable is set', async () => {
    const source = await readFile(new URL('../../quick-reply-ext/index.js', import.meta.url), 'utf8');
    assert.match(source, /setLocalVariable\("RT", withRosterHeader\(strings\.rsbRT\), true\)/);
});
